CODEX_CHILD_ENVIRONMENT_EXCLUDED = frozenset(
    (
        "CODEX_SESSION_ID",
        "CODEX_THREAD_ID",
        "CODEX_PERMISSION_PROFILE",
        "CODEX_SANDBOX_NETWORK_DISABLED",
        "CODEX_INTERNAL_ORIGINATOR_OVERRIDE",
    )
)


def child_provider_environment(executable, *, home=None, codex_home=None):
    """Return one bounded child environment for every local provider launch.

    Claude keeps the inherited environment.  Codex loses only parent-task and
    parent-sandbox bindings; authentication and ordinary process settings stay
    inherited unless the installed supervisor supplies its explicit HOME and
    CODEX_HOME values.  This changes no argv, cwd, sandbox mode or repository
    path and therefore grants no additional N.H access.
    """
    if executable not in ("codex", "claude"):
        raise ValueError("unknown child provider executable %r" % executable)
    env = os.environ.copy()
    if executable == "codex":
        for name in CODEX_CHILD_ENVIRONMENT_EXCLUDED:
            env.pop(name, None)
        # Resume state belongs to the Codex SQLite home, not to the parent
        # desktop task identity.  Removing this variable made a newly launched
        # CLI look in a different database and report that the checkpointed
        # thread did not exist.  Preserve the inherited database root and make
        # a relative or redundant spelling deterministic without resolving
        # symlinks or changing the storage location it denotes.
        sqlite_home = env.get("CODEX_SQLITE_HOME")
        if sqlite_home:
            env["CODEX_SQLITE_HOME"] = os.path.normpath(
                os.path.abspath(os.path.expanduser(sqlite_home))
            )
        if home is not None:
            env["HOME"] = home
        if codex_home is not None:
            env["CODEX_HOME"] = codex_home
    elif home is not None or codex_home is not None:
        raise ValueError("Codex-specific environment overrides require codex")
    return env

