LIVE_PROGRESS_LOG_BASENAME = "nh_live_progress.log"


def live_progress_log_path():
    state_dir = os.environ.get("NH_LOOP_INTERVIEW_STATE_DIR") or DEFAULT_INTERVIEW_STATE_DIR
    return os.path.join(os.path.dirname(os.path.abspath(state_dir)), LIVE_PROGRESS_LOG_BASENAME)


def live_log(text):
    """Append one timestamped line to the live diary.  Never raises.

    NH_LOOP_LIVE_LOG=0 in the environment silences it (used when the test
    suite is run, so test commands never write into the real diary).
    """
    if os.environ.get("NH_LOOP_LIVE_LOG") == "0":
        return
    try:
        line = "%s  %s\n" % (time.strftime("%Y-%m-%d %H:%M:%S"), " ".join(str(text).split()))
        fd = os.open(live_progress_log_path(), os.O_WRONLY | os.O_CREAT | os.O_APPEND, 0o600)
        try:
            os.write(fd, line.encode("utf-8", "replace"))
            os.fsync(fd)
        finally:
            os.close(fd)
    except OSError:
        pass
