INTERVIEW_REPO_SCAN_MAX_FILES = 20000

# Bounds on the CONTROLLER-OWNED relevant-path closure. The closure is derived
# from real source relationships, so it has to be bounded somewhere; it refuses
# rather than samples, because a closure that quietly stopped growing would
# under-state exactly the material a decision needs.
INTERVIEW_CLOSURE_MAX_PATHS = 2000
INTERVIEW_CLOSURE_MAX_FILE_BYTES = 8 * 1024 * 1024
INTERVIEW_CLOSURE_SCAN_MAX_TOTAL_BYTES = 256 * 1024 * 1024
INTERVIEW_CLOSURE_MAX_UNRESOLVED = 200

# What counts as ONE reference from one repository record to another. All three
# are deliberately narrow: a reference is a directory-qualified repository path,
# a bare document filename, or an ALL-CAPS controlled identifier with at least
# two separators. Anything looser would pull ordinary prose into the closure;
# anything tighter would miss the way these records actually name each other.
INTERVIEW_QUALIFIED_PATH_PATTERN = re.compile(
    rb"(?:[0-9A-Za-z_][0-9A-Za-z._-]*/)+[0-9A-Za-z_][0-9A-Za-z._-]*"
)
INTERVIEW_DOCUMENT_NAME_PATTERN = re.compile(
    rb"[0-9A-Za-z_][0-9A-Za-z._-]*"
    rb"\.(?:md|txt|json|jsonl|yml|yaml|py|cfg|ini|toml)"
)
INTERVIEW_CONTROLLED_ID_REFERENCE_PATTERN = re.compile(
    rb"\b[A-Z][A-Z0-9]*(?:[_-][A-Z0-9]+){2,}[0-9A-Za-z_]*"
)
# A basename stem shorter than this is too generic to be a controlled identity,
# and treating it as one would drag unrelated records into the closure.
INTERVIEW_CLOSURE_MIN_STEM_CHARS = 8

# ---------------------------------------------------------------------------
# TYPED relationship edges. A reference is not a relationship.
#
# The first closure followed EVERY file that merely mentioned an already-relevant
# path. On the real N.H checkout one controlled-id probe expanded that way to 119
# of 123 files with 131 unresolved references: an accidental whole-repository
# crawl that could fail closed on unrelated prose, and a "relevant source check"
# that had stopped meaning anything.
#
# Relevance is therefore typed, mechanically and by this controller alone:
#
#   * a FORWARD edge is an exact unambiguous reference out of a relevant file --
#     a repository-relative path, a document filename, or a controlled
#     identifier that resolves to exactly one real artefact;
#   * a REVERSE edge is NOT "some file mentions this one". It exists only when
#     the referencing record is itself a status/lineage record BY PATH CATEGORY
#     and names the target ON A LINE that carries an explicit lineage relation --
#     accepts it, closes it, is its receipt, supersedes or replaces it, records a
#     dependency or placement for it, or is the Map entry that names it.
#
# Nothing here reads ordinary prose for meaning and no model decides what is
# relevant: both halves are decided from the real path and from a closed
# controller-owned vocabulary.
INTERVIEW_LINEAGE_EDGE_CATEGORIES = frozenset(
    (
        "acceptance_record",
        "closure_record",
        "receipt",
        "working_record",
        "ness_decision_record",
        "design_and_wiring_map",
        "workflow_record",
        "accepted_package",
        "active_candidate",
        "historical_candidate",
    )
)

# Categories that are INCLUDED in a closure when something genuinely relevant
# names them, but that the walk never expands OUT of.
#
# The governing authorities and the Map sit at the top of the authority order:
# practically everything names them and they name practically everything, so
# walking through one turns any closure into the whole repository. That is
# exactly the "generic authority-name mention" expansion that has to stop. They
# lose nothing by being terminal -- covering them is separately MANDATORY, via
# the required-file check -- and their own
# unresolved prose references are not counted as unknowns about a package,
# because the walk never treated them as claims about one.
INTERVIEW_TERMINAL_CLOSURE_CATEGORIES = frozenset(
    (
        "governing_authority",
        "design_and_wiring_map",
        "operational_instruction",
    )
)

# The closed vocabulary that makes a reverse reference a LINEAGE reference. It
# is matched case-insensitively against the single LINE the reference occurs on,
# so a record that accepts, closes, receipts, supersedes, replaces, withdraws,
# depends on or places the target is an edge, and a record that happens to
# mention it in a sentence is not.
INTERVIEW_LINEAGE_MARKER_PATTERN = re.compile(
    rb"(?i)(?:"
    rb"accept(?:s|ed|ance)?|"
    rb"close(?:s|d)?|closure|package_complete|"
    rb"receipt|"
    rb"supersed(?:e|es|ed|ing|ure)|"
    rb"replac(?:e|es|ed|ing|ement)|"
    rb"withdraw(?:n|s|al)?|"
    rb"depend(?:s|ent|ency|encies)|"
    rb"placement|placed[ _]in|"
    rb"blocker|"
    rb"register[ _]id|"
    rb"lineage|predecessor|prior[ _]candidate|"
    rb"amend(?:s|ed|ment)?|"
    rb"(?:revision|version)[ _]of|"
    rb"map[ _]entry"
    rb")"
)

# One file's bytes are scanned line-by-line for lineage edges. A single line
# longer than this cannot be a record entry naming a package; it is skipped for
# LINEAGE purposes only, so an over-long line can never manufacture an edge.
INTERVIEW_LINEAGE_MAX_LINE_BYTES = 8192

NESS_KEY_PATTERN = re.compile(r"^[A-Za-z0-9][A-Za-z0-9._:-]{0,119}$")
# A dependency may be named plainly -- meaning THIS package's dependency of that
# name -- or explicitly qualified with the package it belongs to. The separator
# is deliberately a character the plain key grammar above cannot contain, so the
# two forms can never be confused and a qualified identity can never be spelled
# by accident.
NESS_DEPENDENCY_PACKAGE_SEPARATOR = "|"
NESS_QUALIFIED_DEPENDENCY_PATTERN = re.compile(
    r"^[A-Za-z0-9][A-Za-z0-9._:-]{0,119}\|[A-Za-z0-9][A-Za-z0-9._:-]{0,119}$"
)
NESS_OPTION_ID_PATTERN = re.compile(r"^[a-z0-9][a-z0-9_-]{0,39}$")
NESS_QUESTION_ID_PATTERN = re.compile(r"^q_[0-9a-f]{16}$")
NESS_FORM_GENERATION_PATTERN = re.compile(r"^g_[0-9a-f]{16}$")
INTERVIEW_SET_ID_PATTERN = re.compile(r"^vs_[0-9a-f]{32}$")
INTERVIEW_ROUTED_SIGNAL_ID_PATTERN = re.compile(r"^rs_[0-9a-f]{32}$")

