def supervisor_output_schema_for_kind(kind, launch_binding=None):
    """The ONE place the supervised transport chooses a typed reply schema.

    Piece-3 validation keeps a frozen schema from its launch binding when one
    was recorded; coverage review gets its typed schema; every other kind gets
    None (the argv builder then applies the generic object fallback).
    """
    if kind == "gpt_question_validation":
        return (
            (launch_binding or {}).get("output_schema")
            or question_validation_model_output_schema()
        )
    if kind == "gpt_question_coverage_review":
        return question_coverage_review_model_output_schema()
    return None


def codex_structured_output_schema_errors(value, path="$"):
    """Reject unsupported schema keywords before a Codex process can launch.

    The provider-facing schema is intentionally only the small structured-output
    subset N.H needs for shape, required fields, controlled values, nesting and
    nullability. Stronger limits (including uniqueness, cardinality, numeric
    ranges, byte-exact evidence and provenance) remain enforced by the existing
    local validator after generation.
    """
    errors = []
    if not isinstance(value, dict):
        return ["%s is not a schema object" % path]
    unsupported = sorted(set(value) - CODEX_STRUCTURED_OUTPUT_SCHEMA_KEYS)
    if unsupported:
        errors.append(
            "%s uses unsupported Codex output-schema keys: %s"
            % (path, ", ".join(unsupported))
        )
    properties = value.get("properties")
    if properties is not None:
        if not isinstance(properties, dict):
            errors.append("%s.properties is not an object" % path)
        else:
            required = value.get("required")
            if not isinstance(required, list) or set(required) != set(properties):
                errors.append(
                    "%s must require every declared structured-output property" % path
                )
            if value.get("additionalProperties") is not False:
                errors.append(
                    "%s must refuse additional structured-output properties" % path
                )
            for key, child in properties.items():
                errors.extend(
                    codex_structured_output_schema_errors(
                        child, "%s.properties.%s" % (path, key)
                    )
                )
    if "items" in value:
        errors.extend(
            codex_structured_output_schema_errors(value["items"], path + ".items")
        )
    if "anyOf" in value:
        branches = value["anyOf"]
        if not isinstance(branches, list) or not branches:
            errors.append("%s.anyOf is not a non-empty list" % path)
        else:
            for index, child in enumerate(branches):
                errors.extend(
                    codex_structured_output_schema_errors(
                        child, "%s.anyOf[%d]" % (path, index)
                    )
                )
    return errors

