def interview_interpretation_settles(value):
    """Whether one re-derived answer interpretation settles its own question."""
    status = value.get("status") if isinstance(value, dict) else value
    return status in (
        INTERVIEW_INTERPRETATION_SELECTED,
        INTERVIEW_INTERPRETATION_OWN_WORDS,
    )

