# Bundle Seven remain readable history.  They cannot become current authority
# because current_bundle_seven_baseline() separately requires today's source
# binding and the current eleven-package plan.
BUNDLE_SEVEN_LEGACY_PACKAGE_IDS = tuple(
    package_id
    for package_id, _title, _kind in BUNDLE_SEVEN_EXPECTED_PACKAGES
    if package_id != "MUSIC_SYSTEM"
)


def bundle_seven_recorded_package_ids_are_supported(recorded_ids):
    """Accept authenticated historical inventories without making them current."""
    if not isinstance(recorded_ids, list) or not all(
        isinstance(package_id, str) for package_id in recorded_ids
    ):
        return False
    supported = (
        tuple(item[0] for item in BUNDLE_SEVEN_EXPECTED_PACKAGES),
        BUNDLE_SEVEN_LEGACY_PACKAGE_IDS,
    )
    return any(
        len(recorded_ids) == len(package_ids)
        and set(recorded_ids) == set(package_ids)
        for package_ids in supported
    )
