        check_required_source_coverage=check_required_source_coverage,
        interview_package_scope_id=interview_package_scope_id,
        interview_package_key=interview_package_key,
        is_new_candidate_path=is_new_candidate_path,
        source_root_identity=_continuation_source_root_identity,
        current_source_binding=_continuation_current_source_binding,
        current_source_byte_snapshot=_continuation_current_source_byte_snapshot,
        next_package_action_by_classification=NEXT_PACKAGE_ACTION_BY_CLASSIFICATION,
        scope_anchor_validations=scope_anchor_validations,
